from pathlib import Path
import subprocess

base = 'a38f35e579dfdfae370aeadbfd957fb11a41a1fb'
paths = [Path(line) for line in Path('/tmp/issue-749-p4-paths.txt').read_text().splitlines()]
aggregate = Path('MIPStarRE/QPBT/Combining/DirectLowDegree/Transport/Consistency.lean')

def module_doc_end(text: str, start: int) -> int:
    if not text.startswith('/-"'!'"', start):
        raise ValueError(f'module docstring not found at byte {start}')
    depth = 0
    i = start
    while i < len(text):
        if text.startswith('/-', i):
            depth += 1
            i += 2
        elif text.startswith('-/', i):
            depth -= 1
            i += 2
            if depth == 0:
                return i
        else:
            i += 1
    raise ValueError('unterminated module docstring')

def convert(path: Path, old: str) -> str:
    lines = old.splitlines(keepends=True)
    import_count = 0
    while import_count < len(lines) and lines[import_count].startswith('import '):
        lines[import_count] = 'public ' + lines[import_count]
        import_count += 1
    if import_count == 0:
        raise ValueError(f'{path}: no leading imports')
    body = ''.join(lines)
    if path "'!= aggregate:
        offset = sum(len(line) for line in lines[:import_count])
        while offset < len(body) and body[offset] in '"' \\t\\r\\n':
            offset += 1
        end = module_doc_end(body, offset)
        body = body[:end] + '\\n\\n@[expose] public section' + body[end:]
    return 'module\\n\\n' + body

def normalize(new: str) -> str:
    new = new.removeprefix('module\\n\\n')
    new = new.replace('public import ', 'import ')
    new = new.replace('\\n@[expose] public section\\n', '')
    return new

candidates = {}
for path in paths:
    old = subprocess.check_output(['git', 'show', f'{base}:{path}'], text=True)
    current = path.read_text(encoding='utf-8')
    if current "'!= old:
        raise SystemExit(f'"'{path}: worktree differs from authorized base before conversion')
    new = convert(path, old)
    if normalize(new) "'!= old:
        raise SystemExit(f'"'{path}: candidate does not normalize exactly to base')
    candidates[path] = new

for path, new in candidates.items():
    path.write_text(new, encoding='utf-8')

print(f'converted={len(candidates)} leaves={len(candidates)-1} aggregates=1 base={base}')
PY"

